INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch11$PT159-S3-Q6$batch11$, 159, 3, 6, $batch11$Weaken$batch11$, $batch11$A tiny crab that lives 550 meters below the surface of the Gulf of Mexico has been found to have eyes that are sensitive to ultraviolet light. But ultraviolet light from the sun cannot penetrate to that depth. If the crab’s ultraviolet receptors developed as an adaptation to the depths, they are probably for detecting light from bioluminescent organisms. In that case, since the crab is not itself bioluminescent, it probably hunts bioluminescent prey.$batch11$, $batch11$Which one of the following, if true, would most weaken the argument?$batch11$, $batch11$E$batch11$, true, $batch11$Batch 11; question text from local bank.$batch11$ FROM lr_sections s WHERE s.preptest=159 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT159-S3-Q6$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$A$batch11$, $batch11$A trait that serves no function tends to be lost over time.$batch11$, $batch11$Irrelevant$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT159-S3-Q6$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$A$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$B$batch11$, $batch11$Prey is not plentiful at the depth at which the crabs are found.$batch11$, $batch11$Irrelevant$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT159-S3-Q6$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$B$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$C$batch11$, $batch11$The crabs can detect each other by nonvisual means.$batch11$, $batch11$Irrelevant$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT159-S3-Q6$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$C$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$D$batch11$, $batch11$It takes many generations to develop sensitivity to ultraviolet light.$batch11$, $batch11$Irrelevant$batch11$, false FROM lr_questions q WHERE q.qid=$batch11$PT159-S3-Q6$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$D$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch11$E$batch11$, $batch11$The crab’s most dangerous predators are bioluminescent.$batch11$, $batch11$Correct$batch11$, true FROM lr_questions q WHERE q.qid=$batch11$PT159-S3-Q6$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch11$E$batch11$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch11$PT159-S3-Q6$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch11$Conclusion$batch11$, $batch11$The crab probably hunts bioluminescent prey.$batch11$), (1, $batch11$Evidence$batch11$, $batch11$Sunlight doesn't reach the crab's depth. If its ultraviolet receptors are an adaptation to the depths, they probably detect light from bioluminescent organisms. The crab isn't bioluminescent itself.$batch11$), (2, $batch11$Evaluate$batch11$, $batch11$The argument concludes the crab must be watching for prey. But seeing bioluminescent organisms could help in other ways. If the crab's most dangerous predators glow, the eyes could be for spotting them.$batch11$), (3, $batch11$Goal$batch11$, $batch11$Give another reason the crab would need to see bioluminescent organisms.$batch11$)) v(position,label,body) WHERE q.qid=$batch11$PT159-S3-Q6$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch11$A$batch11$, $batch11$Unused traits fading supports the eyes having some function, but not which one.$batch11$), ($batch11$B$batch11$, $batch11$Scarce prey doesn't mean the crab isn't hunting the glowing kind.$batch11$), ($batch11$C$batch11$, $batch11$Detecting other crabs by other means doesn't change why its eyes see ultraviolet light.$batch11$), ($batch11$D$batch11$, $batch11$How long the trait took to develop doesn't affect what it's for.$batch11$), ($batch11$E$batch11$, $batch11$If its main predators glow, the eyes may be for avoiding them, not hunting.$batch11$)) v(letter,body) WHERE q.qid=$batch11$PT159-S3-Q6$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
